[{"order":1,"type":"heading","text":"Mastering File Uploads, Downloads, and Native Events in Cypress"},{"order":2,"type":"paragraph","text":"Automating complex browser interactions like handling hidden file inputs, verifying downloaded files, and triggering native mouse or keyboard events is crucial for robust end-to-end testing. This tutorial explores advanced Cypress techniques to handle these scenarios seamlessly."},{"order":3,"type":"subheading","text":"1. Handling File Uploads"},{"order":4,"type":"paragraph","text":"Cypress provides the 'attachFile' command through the 'cypress-file-upload' plugin to handle file inputs. Often, file input elements are hidden from view, but Cypress can still attach files directly to them without needing to interact with the hidden DOM elements manually."},{"order":5,"type":"code","text":"describe('File Upload Test', () => {
  it('successfully uploads a profile picture', () => {
    cy.visit('/profile');
    const filePath = 'images/avatar.png';
    cy.get('input[type="file"]').attachFile(filePath);
    cy.get('#submit-btn').click();
    cy.get('.success-message').should('contain', 'Upload complete');
  });
});"},{"order":6,"type":"subheading","text":"2. Handling File Downloads"},{"order":7,"type":"paragraph","text":"Cypress runs inside the browser and cannot directly access the operating system's file system through native browser APIs. However, you can test downloads by asserting against the 'downloads' folder or by making an HTTP request to verify the file endpoint."},{"order":8,"type":"code","text":"describe('File Download Test', () => {
  it('downloads a report and verifies existence', () => {
    cy.visit('/reports');
    cy.get('#download-pdf-btn').click();
    const downloadsFolder = Cypress.config('downloadsFolder');
    cy.readFile(path.join(downloadsFolder, 'report.pdf'), 'binary', { timeout: 15000 })
      .should('exist');
  });
});"},{"order":9,"type":"subheading","text":"3. Triggering Native Events"},{"order":10,"type":"paragraph","text":"Standard Cypress commands like 'click()' and 'type()' trigger synthetic events. Sometimes, complex web components or legacy code require actual native browser events. You can use the 'trigger' command or the 'cypress-real-events' plugin to simulate authentic mouse and touch interactions."},{"order":11,"type":"code","text":"describe('Native Events Test', () => {
  it('performs a native hover and drag-and-drop', () => {
    cy.visit('/dashboard');
    cy.get('.dropdown-menu').trigger('mouseover');
    cy.get('.menu-item').should('be.visible');

    // Using real events plugin for native touch/hover
    cy.get('#draggable').realMouseDown();
    cy.get('#dropzone').realMouseMove(100, 100).realMouseUp();
  });
});"},{"order":12,"type":"subheading","text":"Best Practices and Summary"},{"order":13,"type":"bullet_point","text":"Always place test fixtures in the 'cypress/fixtures' folder to keep upload paths predictable."},{"order":14,"type":"bullet_point","text":"Configure your 'cypress.config.js' to define custom download directories when testing file downloads."},{"order":15,"type":"bullet_point","text":"Prefer standard Cypress commands, falling back to native trigger methods only when working with complex canvas elements or third-party widgets."}]
